/* ---------- assignment ---------- */
function gpUsersOf(role, bid) { const U = users().filter(u => u.status === 'Active' && userRoles(u).includes(role)); if (!bid) return U; const bi = gpBi(bid); const inScope = U.filter(u => { try { return scopeOf(u).has(bi); } catch (e) { return false; } }); return inScope.length ? inScope : U.filter(u => u.branch === bid); }
function gpAssign(det, bid) { const pick = role => { const L = gpUsersOf(role, bid); return L[0] ? L[0].id : ''; }; let owner = pick(det.owner); if (!owner && bid) owner = pick('Principal'); if (!owner) owner = pick('Super Admin'); let rev = pick(det.reviewer); if (!rev || rev === owner) rev = pick(bid ? 'Zonal Director' : 'CFO') || pick('Super Admin'); return { owner, ownerRole: det.owner, reviewer: rev, reviewerRole: det.reviewer }; }
const gpUserName = id => (users().find(u => u.id === id) || {}).name || '';
const gpDue = r => r.state === 'Resolved' || r.state === 'Rejected' ? false : r.due < PROC_TODAY;
