  GP_DET.forEach(det => { const r = gpRule(det.id); if (!r.on) return; let L = []; try { L = det.run(c, r) || []; } catch (e) { errs.push(det.id + ': ' + e.message); return; } L.forEach(g => { found[g.key] = 1; const ex = d.rec.find(x => x.key === g.key && gpOpen(x)); if (ex) { if (ex.text !== g.text || ex.impact !== (g.impact || 0)) { ex.text = g.text; ex.impact = g.impact || 0; updated++; } ex.lastSeen = PROC_TODAY; return; } const prior = d.rec.filter(x => x.key === g.key).length; const as = gpAssign(det, g.bid); d.seq++; const rec = { id: gpId('GP'), no: `GAP-${String(d.seq).padStart(5, '0')}`, key: g.key, det: det.id, cat: det.cat, sub: det.sub, text: g.text, bid: g.bid || '', impact: g.impact || 0, risk: g.risk || det.risk, action: det.action, owner: as.owner, ownerRole: as.ownerRole, reviewer: as.reviewer, reviewerRole: as.reviewerRole, first: PROC_TODAY, lastSeen: PROC_TODAY, due: pcAddDays(PROC_TODAY, det.due), state: 'Open', esc: -1, escAt: [], reopened: prior, evidence: '', notes: [], hist: [{ at: nowIso(), by: 'System', to: 'Open', note: 'Detected by rule ' + det.id }] }; d.rec.unshift(rec); created++; }); });
  d.rec.forEach(x => { if (gpOpen(x) && !found[x.key]) { if ((x.escAt || []).length || x.state !== 'Open') { x.state = 'Resolved'; x.resolvedAt = nowIso(); x.resolution = 'Cleared automatically: no longer detected on ' + PROC_TODAY; x.hist.unshift({ at: nowIso(), by: 'System', to: 'Resolved', note: x.resolution }); } else { x.state = 'Resolved'; x.resolvedAt = nowIso(); x.resolution = 'Cleared automatically: no longer detected'; x.hist.unshift({ at: nowIso(), by: 'System', to: 'Resolved', note: x.resolution }); } cleared++; } });
  let notified = gpEscalate(d);
  d.rec.filter(r => gpOpen(r) && gpDue(r) && r.remindedOn !== PROC_TODAY && r.owner).forEach(r => { try { fnNotify([r.owner], `Reminder: ${r.no} ${r.sub}${r.bid ? ' · ' + gpBr(r.bid) : ''} is overdue since ${r.due}. ${r.action}`, r.no, 'gaps'); } catch (e) { } r.remindedOn = PROC_TODAY; r.reminders = (r.reminders || 0) + 1; notified++; });
  d.runs.unshift({ at: nowIso(), by: (App.user || {}).name || 'System', created, updated, cleared, notified, open: d.rec.filter(gpOpen).length, errs, manual: !!(opts && opts.manual) }); if (d.runs.length > 200) d.runs.length = 200;
